    std::uint64_t maple_desc_start{};
    std::uint64_t maple_desc_nop{};
    std::uint64_t maple_desc_other{};
    std::uint64_t maple_recv_fixups{};
    std::uint64_t maple_dma_irqs{};
    std::array<std::uint32_t, 3> holly_pending{};
